#include <iostream>

namespace geom {
    struct Point { int x, y; };
    std::ostream& operator<<(std::ostream& os, const Point& p) {
        return os << "Point(" << p.x << ',' << p.y << ')';
    }
}

int main() {
    geom::Point p{5, 9};
    std::cout << p << '\n';   // ADL 把 geom::operator<< 拉入候选
}
